//-----------------------------------------------------------
data class AssignOrderToGiftCardRedemptionCommand(@TargetAggregateIdentifier  val giftCardRedemptionId: UUID, val assignment: Order )

//-----------------------------------------------------------
// Command for unassigning a Order to a GiftCardRedemption
//-----------------------------------------------------------
data class UnAssignOrderFromGiftCardRedemptionCommand(@TargetAggregateIdentifier  val giftCardRedemptionId: UUID )

// multiple association commands

//-----------------------------------------------------------
// Command for producing an instance of a Payout
//-----------------------------------------------------------
data class CreatePayoutCommand(
    @TargetAggregateIdentifier var payoutId: UUID? = null,
    var payoutNumber: String? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "amount_amount")),
      AttributeOverride( name = "currency", column = Column(name = "amount_currency"))
    )
    var amount: Money? = null,
    var scheduledDate:  Date? = null,
    var paidDate:  Date? = null,
    @Enumerated(EnumType.STRING) var status: PayoutStatus? = null
)
//-----------------------------------------------------------
// Command for modifying an instance of a Payout
//-----------------------------------------------------------
data class UpdatePayoutCommand(
    @TargetAggregateIdentifier var payoutId: UUID? = null,
    var payoutNumber: String? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "amount_amount")),
      AttributeOverride( name = "currency", column = Column(name = "amount_currency"))
    )
    var amount: Money? = null,
    var scheduledDate:  Date? = null,
    var paidDate:  Date? = null,
    var seller: Seller? = null,
    var orders:  Set<Order>? = null,
    @Enumerated(EnumType.STRING) var status: PayoutStatus? = null
)
//-----------------------------------------------------------
// Command for removing an instance of a Payout
//-----------------------------------------------------------
data class DeletePayoutCommand(@TargetAggregateIdentifier  var payoutId: UUID? = null)

// single association commands
//-----------------------------------------------------------
// Command for assigning a Seller to a Payout
//-----------------------------------------------------------
data class AssignSellerToPayoutCommand(@TargetAggregateIdentifier  val payoutId: UUID, val assignment: Seller )

//-----------------------------------------------------------
// Command for unassigning a Seller to a Payout
//-----------------------------------------------------------
data class UnAssignSellerFromPayoutCommand(@TargetAggregateIdentifier  val payoutId: UUID )

// multiple association commands
//-----------------------------------------------------------
// Command for adding a Order to a Payout
//-----------------------------------------------------------
data class AssignOrdersToPayoutCommand(@TargetAggregateIdentifier  val payoutId: UUID, val addTo: Order )
//-----------------------------------------------------------
// Command for removing a Order from a Payout
//-----------------------------------------------------------
data class RemoveOrdersFromPayoutCommand(@TargetAggregateIdentifier  val payoutId: UUID, val removeFrom: Order )



